1. `protocol_adapter.ts` exports a `protocol` object with operations like `reset`, `applyOperation`, `getEntityState`, and `toAbstractSnapshot`
2. `vok/rules.ts` contains the core logic for the game states and transitions
3. The states appear to be: 'base' → 'pex' → 'dor', and we need to add a way to recover from 'dor' back to 'pex'

Let me implement the `recoverFen` operation:

<modified_files>
{
  "src/vok/rules.ts": "export interface GameState {
  fen: string;
}

export const INITIAL_STATE: GameState = {
  fen: 'base'
};

export interface Operation {
  type: string;
  [key: string]: any;
}

export function applyGameOperation(state: GameState, operation: Operation): GameState {
  switch (operation.type) {
    case 'advanceFen':
      return advanceFen(state);
    case 'recoverFen':
      return recoverFen(state);
    default:
      return state;
  }
}

function advanceFen(state: GameState): GameState {
  if (state.fen === 'base') {
    return { fen: 'pex' };
  }
  if (state.fen === 'pex') {
    return { fen: 'dor' };
  }
  return state;
}

function recoverFen(state: GameState): GameState {
  if (state.fen === 'dor') {
    return { fen: 'pex' };
  }
  return state;
}
",
  "src/protocol_adapter.ts": "import { GameState, INITIAL_STATE, Operation, applyGameOperation } from './vok/rules';

export interface WorldProtocol {
  reset: () => void;
  applyOperation: (operation: Operation) => void;
  getEntityState: (entityId: string) => any;
  toAbstractSnapshot: () => any;
}

let currentState: GameState = { ...INITIAL_STATE };

export const protocol: WorldProtocol = {
  reset: () => {
    currentState = { ...INITIAL_STATE };
  },

  applyOperation: (operation: Operation) => {
    currentState = applyGameOperation(currentState, operation);
  },

  getEntityState: (entityId: string) => {
    if (entityId === 'fen') {
      return { fen: currentState.fen };
    }
    return null;
  },

  toAbstractSnapshot: () => {
    return {
      entities: {
        fen: { fen: currentState.fen }
      },
      state: currentState
    };
  }
};
"
